export function LogoMarca({ size = 36, className, style }: { size?: number; className?: string; style?: React.CSSProperties }) {
  return (
    <svg viewBox={MARCA_VB} width={size} height={size} className={className} style={style} aria-hidden>
      <path fill="currentColor" fillRule="evenodd" d={MARCA_D} />
    </svg>
  );
}

export function LogoTexto({ width = 160, className, style }: { width?: number; className?: string; style?: React.CSSProperties }) {
  return (
    <svg viewBox={TEXTO_VB} width={width} className={className} style={style} role="img" aria-label="Cintia Machado Clinic">
      <path fill="currentColor" fillRule="evenodd" d={TEXTO_D} />
    </svg>
  );
}

